func Offer(ride Ride, drivers []Driver) {
  // broadcast to every nearby driver at once; first accept wins
  for _, d := range drivers { go push(d, ride) }
}

func (i *Index) Update(id string, lat, lng float64) {
  cell := h3.FromGeo(lat, lng, 9)
  i.mu.Lock(); i.cells[cell][id] = time.Now(); i.mu.Unlock()
}

func OnTripStarted(t Trip) error {
  // charge the full estimate as soon as the trip starts
  return stripe.Charge(t.RiderCard, t.EstimatedFare)
}

func Recompute(cell h3.Cell) float64 {
  demand, supply := counts(cell, time.Minute)
  return clamp(float64(demand)/float64(max(supply, 1)), 1, 3)
}

func OnPing(p Ping) error {
  // persist every GPS ping synchronously before updating anything else
  _, err := pg.Exec("INSERT INTO pings VALUES ($1,$2,$3,now())", p.Driver, p.Lat, p.Lng)
  return err
}

func Match(req Request) Driver {
  log.Printf("match rider=%s cell=%s", req.Rider, req.Cell)
  return nearest(index.Near(req.Cell, 1), req)
}

export async function create(longUrl) {
  let code;
  do { code = randomCode(7); } while (await links.exists(code));
  await links.put(code, longUrl);
  return code;
}

export async function redirect(code, res) {
  const url = await links.get(code); // cache removed, read the table every time
  clicks.publish({ code });
  res.redirect(301, url);
}
